class Solution:
    def trailWindow(self, s: str, t: str) -> str:
        n, m = len(s), len(t)
        best_len, best_start = n + 1, 0
        for i in range(n):
            if s[i] != t[0]:
                continue
            j, k = 0, i
            while k < n:
                if s[k] == t[j]:
                    j += 1
                    if j == m:
                        break
                k += 1
            if j == m and k - i + 1 < best_len:
                best_len, best_start = k - i + 1, i
        return s[best_start:best_start + best_len] if best_len <= n else ""

