class Solution {
    public String trailWindow(String s, String t) {
        int n = s.length(), m = t.length(), bestLen = n + 1, bestStart = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) != t.charAt(0)) continue;
            int j = 0, k = i;
            for (; k < n; k++) if (s.charAt(k) == t.charAt(j) && ++j == m) break;
            if (j == m && k - i + 1 < bestLen) { bestLen = k - i + 1; bestStart = i; }
        }
        return bestLen <= n ? s.substring(bestStart, bestStart + bestLen) : "";
    }
}

