class Solution {
    public String trailWindow(String s, String t) {
        int n = s.length(), m = t.length(), bestLen = n + 1, bestStart = 0;
        int[] start = new int[m + 1];
        Arrays.fill(start, -1);
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            for (int j = m; j >= 1; j--)
                if (t.charAt(j - 1) == c) start[j] = j == 1 ? i : start[j - 1];
            if (start[m] >= 0 && i - start[m] + 1 < bestLen) { bestLen = i - start[m] + 1; bestStart = start[m]; }
        }
        return bestLen <= n ? s.substring(bestStart, bestStart + bestLen) : "";
    }
}

